// Reef tank pH logger.
// Linearized probe on A0, optional low-pH LED on D13, UART log at 9600.

const int PROBE_PIN = A0;
const int ALERT_PIN = 13;
const float ALERT_PH = 7.20f;
const float ALERT_HYST = 0.05f;
const unsigned long LOG_PERIOD_MS = 1000;

unsigned long lastLogMs = 0;
unsigned long sampleCount = 0;
float lastPh = 0.0f;
float phMin = 14.0f;
float phMax = 0.0f;
bool alertOn = false;

float adcToMillivolts(int raw)
{
    return raw * (5000.0f / 1023.0f);
}

float computePh(float millivolts)
{
    return millivolts / 500.0f;
}

void trackRange(float ph)
{
    if (ph < phMin)
    {
        phMin = ph;
    }
    if (ph > phMax)
    {
        phMax = ph;
    }
}

void setAlert(bool on)
{
    alertOn = on;
    digitalWrite(ALERT_PIN, on ? HIGH : LOW);
}

void writeLogLine()
{
    Serial.print("pH: ");
    Serial.println(lastPh, 2);
}

void setup()
{
    pinMode(ALERT_PIN, OUTPUT);
    digitalWrite(ALERT_PIN, LOW);
    Serial.begin(9600);
    lastLogMs = millis();
}

void loop()
{
    int raw = analogRead(PROBE_PIN);
    float mv = adcToMillivolts(raw);
    lastPh = computePh(mv);
    sampleCount++;
    trackRange(lastPh);

    if (lastPh < ALERT_PH)
    {
        setAlert(true);
    }
    else if (lastPh >= ALERT_PH + ALERT_HYST)
    {
        setAlert(false);
    }

    unsigned long now = millis();
    if (now - lastLogMs >= LOG_PERIOD_MS)
    {
        lastLogMs = now;
        writeLogLine();
    }
}

// Attic ridge-vent controller for an Uno.
// LM35 on A0, relay driver on D8, momentary override on D3 (pull-up).

const int TEMP_PIN = A0;
const int FAN_PIN = 8;
const int OVERRIDE_PIN = 3;

const float FAN_ON_C = 42.0f;
const float FAN_OFF_C = 38.0f;
const float MV_PER_C = 10.0f;
const unsigned long SAMPLE_MS = 50;
const unsigned long STATUS_MS = 1000;
const unsigned long CONFIRM_MS = 300;

bool fanRunning = false;
bool pendingState = false;
bool havePending = false;
unsigned long pendingSinceMs = 0;
unsigned long lastSampleMs = 0;
unsigned long lastStatusMs = 0;
float lastTempC = 0.0f;

float readAtticTempC()
{
    int raw = analogRead(TEMP_PIN);
    float millivolts = raw * (5000.0f / 1023.0f);
    return millivolts / MV_PER_C;
}

void applyFan(bool wantOn)
{
    fanRunning = wantOn;
    digitalWrite(FAN_PIN, wantOn ? HIGH : LOW);
}

void publishStatus()
{
    Serial.print("attic: ");
    Serial.print(lastTempC, 1);
    Serial.print(" C fan=");
    Serial.println(fanRunning ? "ON" : "OFF");
}

void setup()
{
    pinMode(FAN_PIN, OUTPUT);
    pinMode(OVERRIDE_PIN, INPUT_PULLUP);
    digitalWrite(FAN_PIN, LOW);
    Serial.begin(9600);
    lastSampleMs = millis();
    lastStatusMs = millis();
}

void loop()
{
    unsigned long now = millis();

    if (now - lastSampleMs >= SAMPLE_MS)
    {
        lastSampleMs = now;
        lastTempC = readAtticTempC();

        bool overrideHeld = (digitalRead(OVERRIDE_PIN) == LOW);
        bool wantOn;
        if (overrideHeld)
        {
            wantOn = true;
        }
        else if (lastTempC >= FAN_ON_C)
        {
            wantOn = true;
        }
        else if (lastTempC <= FAN_OFF_C)
        {
            wantOn = false;
        }
        else
        {
            wantOn = fanRunning;
        }

        if (wantOn == fanRunning)
        {
            havePending = false;
        }
        else if (!havePending || pendingState != wantOn)
        {
            pendingState = wantOn;
            pendingSinceMs = now;
            havePending = true;
        }
        else if (now - pendingSinceMs >= CONFIRM_MS)
        {
            applyFan(pendingState);
            havePending = false;
        }
    }

    if (now - lastStatusMs >= STATUS_MS)
    {
        lastStatusMs = now;
        publishStatus();
    }
}

// Blend-tank concentration logger for a process skid.
// Probe on A4 (10 mV/%). Sample button on D5 (pull-up) forces an early print.

const int CONC_PIN = A4;
const int SAMPLE_BTN = 5;
const int WINDOW = 8;
const float MV_PER_PCT = 10.0f;
const unsigned long IDLE_MS = 20;
const unsigned long STATUS_MS = 1000;
const unsigned long BTN_HOLD_MS = 50;

int samples[WINDOW];
int idx = 0;
int n = 0;
float lastPct = 0.0f;
unsigned long lastStatus = 0;
unsigned long batches = 0;
bool btnWasLow = false;
unsigned long btnLowSince = 0;

float rawToPct(int raw)
{
    float mv = raw * (5000.0f / 1023.0f);
    return mv / MV_PER_PCT;
}

void resetWindow()
{
    idx = 0;
    n = 0;
}

void publishPct(float pct)
{
    Serial.print("pct: ");
    Serial.println(pct, 1);
    lastPct = pct;
    batches++;
}

void forceSampleNote()
{
    Serial.print("blend force last=");
    Serial.println(lastPct, 1);
}

void setup()
{
    pinMode(SAMPLE_BTN, INPUT_PULLUP);
    Serial.begin(9600);
    resetWindow();
    lastStatus = millis();
}

void loop()
{
    int raw = analogRead(CONC_PIN);
    samples[idx] = raw;
    idx = (idx + 1) % WINDOW;
    if (n < WINDOW)
    {
        n++;
    }

    unsigned long now = millis();

    if (now - lastStatus >= STATUS_MS)
    {
        lastStatus = now;

        long total = 0;
        for (int i = 0; i < n; i++)
        {
            total += samples[i];
        }
        int avg = (int)(total / n);
        float pct = rawToPct(avg);
        publishPct(pct);

        Serial.print("blend batches=");
        Serial.println(batches);
    }

    bool btnLow = (digitalRead(SAMPLE_BTN) == LOW);
    if (btnLow)
    {
        if (!btnWasLow)
        {
            btnWasLow = true;
            btnLowSince = now;
        }
        else if (now - btnLowSince >= BTN_HOLD_MS)
        {
            forceSampleNote();
            btnWasLow = false;
        }
    }
    else
    {
        btnWasLow = false;
    }

    delay(IDLE_MS);
}

// Small boiler gas-valve thermostat.
// Probe on A1 (10 mV/°C), gas valve on D6, lockout key on D3.

const int TEMP_PIN = A1;
const int VALVE_PIN = 6;
const int LOCK_PIN = 3;
const float FIRE_ON_C = 70.0f;
const float FIRE_OFF_C = 75.0f;
const float FAULT_HIGH_C = 120.0f;
const float FAULT_LOW_C = 5.0f;
const float MV_PER_C = 10.0f;
const unsigned long TICK_MS = 40;
const unsigned long STATUS_MS = 1000;

bool firing = false;
unsigned long lastTick = 0;
unsigned long lastStatus = 0;
float tempC = 0.0f;

float readBoilerC()
{
    int raw = analogRead(TEMP_PIN);
    float mv = raw * (5000.0f / 1023.0f);
    return mv / MV_PER_C;
}

void setValve(bool openValve)
{
    firing = openValve;
    digitalWrite(VALVE_PIN, openValve ? HIGH : LOW);
}

void printStatus()
{
    Serial.print("boiler: ");
    Serial.print(tempC, 1);
    Serial.print(" C valve=");
    Serial.println(firing ? "OPEN" : "SHUT");
}

void setup()
{
    pinMode(VALVE_PIN, OUTPUT);
    pinMode(LOCK_PIN, INPUT_PULLUP);
    setValve(false);
    Serial.begin(9600);
    lastTick = millis();
    lastStatus = millis();
}

void loop()
{
    unsigned long now = millis();

    if (now - lastTick >= TICK_MS)
    {
        lastTick = now;
        tempC = readBoilerC();
        bool locked = (digitalRead(LOCK_PIN) == LOW);
        bool fault = (tempC > FAULT_HIGH_C) || (tempC < FAULT_LOW_C);

        if (locked || fault)
        {
            setValve(false);
        }
        else if (tempC < FIRE_ON_C)
        {
            setValve(true);
        }
        else if (tempC > FIRE_OFF_C)
        {
            setValve(false);
        }
    }

    if (now - lastStatus >= STATUS_MS)
    {
        lastStatus = now;
        printStatus();
    }
}

// Basement sump controller.
// Ultrasonic level proxy as linear voltage on A1, pump contactor on D7,
// silence button on D4 (active LOW, pull-up).

const uint8_t LEVEL_PIN = A1;
const uint8_t PUMP_PIN = 7;
const uint8_t SILENCE_PIN = 4;

const float START_CM = 45.0f;
const float STOP_CM = 30.0f;
const float MV_PER_CM = 10.0f;
const unsigned long POLL_MS = 40;
const unsigned long LOG_MS = 800;
const unsigned long CONFIRM_MS = 300;

bool pumpOn = false;
bool silenceLatched = false;
unsigned long lastPoll = 0;
unsigned long lastLog = 0;
float levelCm = 0.0f;

bool levelCandidate = false;
bool levelPending = false;
unsigned long levelSince = 0;
bool silenceCandidate = false;
unsigned long silenceSince = 0;

float sampleLevelCm()
{
    int adc = analogRead(LEVEL_PIN);
    float mv = adc * (5000.0f / 1023.0f);
    return mv / MV_PER_CM;
}

void setPump(bool on)
{
    pumpOn = on;
    digitalWrite(PUMP_PIN, on ? HIGH : LOW);
}

void emitLog()
{
    Serial.print("sump cm=");
    Serial.print(levelCm, 1);
    Serial.print(" pump=");
    Serial.print(pumpOn ? 1 : 0);
    Serial.print(" mute=");
    Serial.println(silenceLatched ? 1 : 0);
}

void setup()
{
    pinMode(PUMP_PIN, OUTPUT);
    pinMode(SILENCE_PIN, INPUT_PULLUP);
    digitalWrite(PUMP_PIN, LOW);
    Serial.begin(9600);
    lastPoll = millis();
    lastLog = millis();
}

void loop()
{
    unsigned long t = millis();

    // Silence button: require a continuous LOW before latching.
    if (digitalRead(SILENCE_PIN) == LOW)
    {
        if (!silenceCandidate)
        {
            silenceCandidate = true;
            silenceSince = t;
        }
        else if (t - silenceSince >= CONFIRM_MS)
        {
            silenceLatched = true;
            setPump(false);
        }
    }
    else
    {
        silenceCandidate = false;
        // Release the latch once the button is no longer held.
        silenceLatched = false;
    }

    if (t - lastPoll >= POLL_MS)
    {
        lastPoll = t;
        levelCm = sampleLevelCm();

        if (!silenceLatched)
        {
            // Hysteresis: start at/above START_CM, stop at/below STOP_CM.
            bool wantOn = pumpOn;
            if (levelCm >= START_CM)
            {
                wantOn = true;
            }
            else if (levelCm <= STOP_CM)
            {
                wantOn = false;
            }

            // Require the requested state to persist before switching.
            if (wantOn != pumpOn)
            {
                if (!levelPending || levelCandidate != wantOn)
                {
                    levelCandidate = wantOn;
                    levelPending = true;
                    levelSince = t;
                }
                else if (t - levelSince >= CONFIRM_MS)
                {
                    setPump(wantOn);
                    levelPending = false;
                }
            }
            else
            {
                levelPending = false;
            }
        }
    }

    if (t - lastLog >= LOG_MS)
    {
        lastLog = t;
        emitLog();
    }
}

// Foyer wall switch: one pushbutton toggles a lamp channel.
// Button D5 to ground (pull-up), lamp driver D11, status over serial.

const int SWITCH_PIN = 5;
const int LAMP_PIN = 11;
const unsigned long STATUS_EVERY_MS = 1500;
const unsigned long SETTLE_MS = 40;

bool lampLit = false;
int previousRaw = HIGH;
int settledRaw = HIGH;
int candidateRaw = HIGH;
unsigned long candidateSince = 0;
unsigned long lastStatusAt = 0;
unsigned long pressEvents = 0;
unsigned long bootMs = 0;

void driveLamp(bool on)
{
    lampLit = on;
    digitalWrite(LAMP_PIN, on ? HIGH : LOW);
}

void flipLamp()
{
    driveLamp(!lampLit);
    pressEvents++;
}

bool isPressedEdge(int previous, int current)
{
    return previous == HIGH && current == LOW;
}

void reportLamp()
{
    Serial.print("foyer lamp=");
    Serial.println(lampLit ? "ON" : "OFF");
}

void setup()
{
    pinMode(SWITCH_PIN, INPUT_PULLUP);
    pinMode(LAMP_PIN, OUTPUT);
    driveLamp(false);
    Serial.begin(9600);
    previousRaw = digitalRead(SWITCH_PIN);
    settledRaw = previousRaw;
    candidateRaw = previousRaw;
    candidateSince = millis();
    lastStatusAt = millis();
    bootMs = millis();
}

void loop()
{
    int raw = digitalRead(SWITCH_PIN);
    unsigned long now = millis();

    if (raw != candidateRaw)
    {
        candidateRaw = raw;
        candidateSince = now;
    }
    else if (candidateRaw != settledRaw && now - candidateSince >= SETTLE_MS)
    {
        settledRaw = candidateRaw;
        if (isPressedEdge(previousRaw, settledRaw))
        {
            flipLamp();
        }
        previousRaw = settledRaw;
    }

    if (now - lastStatusAt >= STATUS_EVERY_MS)
    {
        lastStatusAt = now;
        reportLamp();
    }
}

// Greenhouse ridge-vent controller.
// Soil-air LM35 on A2, exhaust fan relay on D9, UART status.

const int SENSOR_PIN = A2;
const int FAN_PIN = 9;
const float OPEN_C = 28.0f;
const float CLOSE_C = 24.0f;
const float FAULT_LOW_C = 5.0f;
const float FAULT_HIGH_C = 100.0f;
const float MV_PER_C = 10.0f;
const unsigned long TICK_MS = 50;
const unsigned long STATUS_MS = 1000;
const unsigned long CONFIRM_MS = 300;

bool fanOn = false;
bool pendingOn = false;
unsigned long pendingSince = 0;
bool faultActive = false;
unsigned long lastTick = 0;
unsigned long lastStatus = 0;
unsigned long sampleCount = 0;
float tempC = 0.0f;
float tempMin = 999.0f;
float tempMax = -999.0f;

float readTempC()
{
    int raw = analogRead(SENSOR_PIN);
    float mv = raw * (5000.0f / 1023.0f);
    return mv / MV_PER_C;
}

void trackTemp(float c)
{
    if (c < tempMin)
    {
        tempMin = c;
    }
    if (c > tempMax)
    {
        tempMax = c;
    }
}

void setFan(bool on)
{
    fanOn = on;
    digitalWrite(FAN_PIN, on ? HIGH : LOW);
}

void printStatus()
{
    Serial.print("gh: ");
    Serial.print(tempC, 1);
    Serial.print(" C fan=");
    Serial.println(fanOn ? "ON" : "OFF");
}

void setup()
{
    pinMode(FAN_PIN, OUTPUT);
    digitalWrite(FAN_PIN, LOW);
    Serial.begin(9600);
    lastTick = millis();
    lastStatus = millis();
    pendingOn = fanOn;
    pendingSince = millis();
}

void loop()
{
    unsigned long now = millis();

    if (now - lastTick >= TICK_MS)
    {
        lastTick = now;
        tempC = readTempC();
        sampleCount++;
        trackTemp(tempC);

        bool fault = (tempC < FAULT_LOW_C) || (tempC > FAULT_HIGH_C);
        bool wantOn;

        if (fault)
        {
            wantOn = true;
        }
        else if (faultActive)
        {
            // Leaving a fault: re-evaluate from the band.
            wantOn = (tempC >= OPEN_C) ? true : ((tempC <= CLOSE_C) ? false : fanOn);
        }
        else if (tempC >= OPEN_C)
        {
            wantOn = true;
        }
        else if (tempC <= CLOSE_C)
        {
            wantOn = false;
        }
        else
        {
            wantOn = fanOn;
        }

        if (wantOn != pendingOn)
        {
            pendingOn = wantOn;
            pendingSince = now;
        }

        if (pendingOn != fanOn && (now - pendingSince) >= CONFIRM_MS)
        {
            setFan(pendingOn);
        }

        faultActive = fault;
    }

    if (now - lastStatus >= STATUS_MS)
    {
        lastStatus = now;
        printStatus();
    }
}

// Shop hoist contactor with mushroom e-stop.
// E-stop on D3 (NC to ground via switch, pull-up), contactor on D5.
// Run request on D6 (pull-up).

const int ESTOP_PIN = 3;
const int CONTACTOR_PIN = 5;
const int RUN_PIN = 6;
const unsigned long SETTLE_MS = 30;
const unsigned long BEAT_MS = 1100;

int stableStop = HIGH;
int lastStop = HIGH;
unsigned long stopEdge = 0;
bool contactorOn = false;
unsigned long lastBeat = 0;
unsigned long tripCount = 0;

bool estopActive(int level)
{
    return level == LOW;
}

void setContactor(bool on)
{
    contactorOn = on;
    digitalWrite(CONTACTOR_PIN, on ? HIGH : LOW);
}

void heartbeat()
{
    Serial.print("hoist run=");
    Serial.print(contactorOn ? 1 : 0);
    Serial.print(" trips=");
    Serial.println(tripCount);
}

void setup()
{
    pinMode(ESTOP_PIN, INPUT_PULLUP);
    pinMode(RUN_PIN, INPUT_PULLUP);
    pinMode(CONTACTOR_PIN, OUTPUT);
    setContactor(false);
    Serial.begin(9600);
    stableStop = digitalRead(ESTOP_PIN);
    lastStop = stableStop;
    lastBeat = millis();
}

void loop()
{
    unsigned long now = millis();
    int raw = digitalRead(ESTOP_PIN);

    if (raw != lastStop)
    {
        stopEdge = now;
        lastStop = raw;
    }

    if ((now - stopEdge) >= SETTLE_MS && raw != stableStop)
    {
        if (estopActive(raw) && !estopActive(stableStop))
        {
            tripCount++;
        }
        stableStop = raw;
    }

    bool stopped = estopActive(stableStop);
    bool runReq = (digitalRead(RUN_PIN) == LOW);

    if (stopped)
    {
        setContactor(false);
    }
    else if (runReq)
    {
        setContactor(true);
    }
    else
    {
        setContactor(true);
    }

    if (now - lastBeat >= BEAT_MS)
    {
        lastBeat = now;
        heartbeat();
    }
}

// Bench reagent inject one-shot.
// Start button on D2 (pull-up), inject indicator on D4.
// Heartbeat on UART while idle and during the pulse.

const int START_PIN = 2;
const int INJECT_PIN = 4;
const unsigned long PULSE_MS = 3000;
const unsigned long DEBOUNCE_MS = 30;
const unsigned long HB_MS = 400;

bool pulsing = false;
unsigned long pulseStart = 0;
int stableBtn = HIGH;
int lastBtn = HIGH;
unsigned long btnEdge = 0;
unsigned long lastHb = 0;
unsigned long shots = 0;

void injectHigh()
{
    digitalWrite(INJECT_PIN, HIGH);
}

void injectLow()
{
    digitalWrite(INJECT_PIN, LOW);
}

void sendHb()
{
    Serial.print("inject hb shots=");
    Serial.println(shots);
}

void setup()
{
    pinMode(START_PIN, INPUT_PULLUP);
    pinMode(INJECT_PIN, OUTPUT);
    injectLow();
    Serial.begin(9600);
    stableBtn = digitalRead(START_PIN);
    lastBtn = stableBtn;
    lastHb = millis();
}

void loop()
{
    unsigned long now = millis();
    int raw = digitalRead(START_PIN);

    if (raw != lastBtn)
    {
        btnEdge = now;
        lastBtn = raw;
    }

    if ((now - btnEdge) >= DEBOUNCE_MS && raw != stableBtn)
    {
        stableBtn = raw;
        if (stableBtn == LOW && !pulsing)
        {
            pulsing = true;
            pulseStart = now;
            shots++;
            injectHigh();
            Serial.println("go");
        }
    }

    if (pulsing && (now - pulseStart) >= PULSE_MS)
    {
        pulsing = false;
        injectLow();
    }

    if (now - lastHb >= HB_MS)
    {
        lastHb = now;
        sendHb();
    }
}

// Studio kiln door interlock siren.
// Door-open switch on D2 (pull-up, active LOW), piezo driver on D8.
// Spec requires a serial heartbeat while the siren runs.

const int DOOR_PIN = 2;
const int SIREN_PIN = 8;
const unsigned long SIREN_MS = 2000;
const unsigned long HEARTBEAT_MS = 250;
const unsigned long SETTLE_MS = 40;

unsigned long lastHeartbeat = 0;
unsigned long tripCount = 0;
bool sirenArmed = false;

bool sirenActive = false;
unsigned long sirenStart = 0;

bool pressPending = false;
unsigned long pressStart = 0;

void sirenOn()
{
    digitalWrite(SIREN_PIN, HIGH);
}

void sirenOff()
{
    digitalWrite(SIREN_PIN, LOW);
}

void emitHeartbeat()
{
    Serial.println("hb");
}

bool doorOpen()
{
    return digitalRead(DOOR_PIN) == LOW;
}

void startSirenBurst()
{
    tripCount++;
    sirenOn();
    sirenActive = true;
    sirenStart = millis();
}

void serviceSiren()
{
    if (sirenActive && (millis() - sirenStart >= SIREN_MS))
    {
        sirenOff();
        sirenActive = false;
    }
}

void serviceDoor()
{
    if (sirenActive)
    {
        // Ignore presses while a pulse is running.
        pressPending = false;
        return;
    }

    if (doorOpen())
    {
        if (!pressPending)
        {
            pressPending = true;
            pressStart = millis();
        }
        else if (millis() - pressStart >= SETTLE_MS)
        {
            pressPending = false;
            sirenArmed = true;
            startSirenBurst();
            sirenArmed = false;
        }
    }
    else
    {
        pressPending = false;
    }
}

void setup()
{
    pinMode(DOOR_PIN, INPUT_PULLUP);
    pinMode(SIREN_PIN, OUTPUT);
    sirenOff();
    Serial.begin(9600);
    lastHeartbeat = millis();
}

void loop()
{
    serviceDoor();
    serviceSiren();

    unsigned long now = millis();
    if (now - lastHeartbeat >= HEARTBEAT_MS)
    {
        lastHeartbeat = now;
        emitHeartbeat();
    }
}

// Compact laundry fill/run cycle controller.
// Level probe on A0 (10 mV/cm), fill valve on D9, drum motor on D10.
// Reset button on D4 (pull-up) returns to IDLE.

const int LEVEL_PIN = A0;
const int VALVE_PIN = 9;
const int MOTOR_PIN = 10;
const int RESET_PIN = 4;
const float EMPTY_CM = 10.0f;
const float FULL_CM = 25.0f;
const float RUN_MIN_CM = 20.0f;
const float MV_PER_CM = 10.0f;
const unsigned long TICK_MS = 40;
const unsigned long STATUS_MS = 1000;
const unsigned long CONFIRM_MS = 60;

enum CycleState
{
    ST_IDLE = 0,
    ST_FILL = 1,
    ST_RUN = 2
};

CycleState state = ST_IDLE;
unsigned long lastTick = 0;
unsigned long lastStatus = 0;
float levelCm = 0.0f;
bool pendingActive = false;
bool pendingValue = false;
unsigned long pendingSince = 0;

float readLevelCm()
{
    int raw = analogRead(LEVEL_PIN);
    float mv = raw * (5000.0f / 1023.0f);
    return mv / MV_PER_CM;
}

void driveOutputs()
{
    digitalWrite(VALVE_PIN, state == ST_FILL ? HIGH : LOW);
    digitalWrite(MOTOR_PIN, state == ST_RUN ? HIGH : LOW);
}

void printStatus()
{
    Serial.print("laundry st=");
    Serial.print((int)state);
    Serial.print(" cm=");
    Serial.println(levelCm, 1);
}

// Returns true when the requested condition has held continuously for CONFIRM_MS.
bool confirmed(bool active, bool value, unsigned long now)
{
    if (!active)
    {
        pendingActive = false;
        return false;
    }
    if (!pendingActive || pendingValue != value)
    {
        pendingActive = true;
        pendingValue = value;
        pendingSince = now;
        return false;
    }
    return (now - pendingSince) >= CONFIRM_MS;
}

void setup()
{
    pinMode(VALVE_PIN, OUTPUT);
    pinMode(MOTOR_PIN, OUTPUT);
    pinMode(RESET_PIN, INPUT_PULLUP);
    driveOutputs();
    Serial.begin(9600);
    lastTick = millis();
    lastStatus = millis();
}

void loop()
{
    unsigned long now = millis();

    if (digitalRead(RESET_PIN) == LOW)
    {
        state = ST_IDLE;
        pendingActive = false;
        driveOutputs();
    }

    if (now - lastTick >= TICK_MS)
    {
        lastTick = now;
        levelCm = readLevelCm();

        if (digitalRead(RESET_PIN) == LOW)
        {
            state = ST_IDLE;
            pendingActive = false;
        }
        else if (state == ST_IDLE)
        {
            if (confirmed(levelCm < EMPTY_CM, true, now))
            {
                state = ST_FILL;
                pendingActive = false;
            }
        }
        else if (state == ST_FILL)
        {
            if (confirmed(levelCm >= FULL_CM, true, now))
            {
                state = ST_RUN;
                pendingActive = false;
            }
        }
        else if (state == ST_RUN)
        {
            if (confirmed(levelCm < RUN_MIN_CM, true, now))
            {
                state = ST_IDLE;
                pendingActive = false;
            }
        }

        driveOutputs();
    }

    if (now - lastStatus >= STATUS_MS)
    {
        lastStatus = now;
        printStatus();
    }
}

// Loft cooling fan with hysteresis and a boost button.
// TMP-style linear probe on A3 (10 mV/°C), fan on D5, boost on D4.

const int TEMP_PIN = A3;
const int FAN_PIN = 5;
const int BOOST_PIN = 4;

const float ON_C = 36.0f;
const float OFF_C = 32.0f;
const float MV_PER_C = 10.0f;
const unsigned long SAMPLE_MS = 50;
const unsigned long LOG_MS = 1000;
const int HOLD = 4;
const unsigned long MIN_DWELL_MS = 2500;

bool fanOn = false;
int onHold = 0;
int offHold = 0;
unsigned long lastSample = 0;
unsigned long lastLog = 0;
unsigned long lastChange = 0;
float tempC = 0.0f;

float sampleTempC()
{
    int raw = analogRead(TEMP_PIN);
    float mv = raw * (5000.0f / 1023.0f);
    return mv / MV_PER_C;
}

void driveFan(bool on)
{
    if (on == fanOn)
    {
        return;
    }
    fanOn = on;
    lastChange = millis();
    digitalWrite(FAN_PIN, on ? HIGH : LOW);
}

void logLine()
{
    Serial.print("loft: ");
    Serial.print(tempC, 1);
    Serial.print(" C fan=");
    Serial.println(fanOn ? "ON" : "OFF");
}

void setup()
{
    pinMode(FAN_PIN, OUTPUT);
    pinMode(BOOST_PIN, INPUT_PULLUP);
    digitalWrite(FAN_PIN, LOW);
    Serial.begin(9600);
    lastSample = millis();
    lastLog = millis();
    lastChange = millis();
}

void loop()
{
    unsigned long now = millis();

    if (now - lastSample >= SAMPLE_MS)
    {
        lastSample = now;
        tempC = sampleTempC();

        bool dwellOk = (now - lastChange) >= MIN_DWELL_MS;

        if (digitalRead(BOOST_PIN) == LOW)
        {
            onHold = 0;
            offHold = 0;
            if (dwellOk)
            {
                driveFan(true);
            }
        }
        else
        {
            if (tempC >= ON_C)
            {
                onHold++;
            }
            else
            {
                onHold = 0;
            }
            if (tempC <= OFF_C)
            {
                offHold++;
            }
            else
            {
                offHold = 0;
            }

            if (dwellOk)
            {
                if (onHold >= HOLD)
                {
                    driveFan(true);
                }
                else if (offHold >= HOLD)
                {
                    driveFan(false);
                }
            }
        }
    }

    if (now - lastLog >= LOG_MS)
    {
        lastLog = now;
        logLine();
    }
}

// Greenhouse mist injector timed pulse.
// Trigger on D4 (pull-up), injector on D9, ready lamp on D12.

const int TRIG_PIN = 4;
const int INJ_PIN = 9;
const int READY_PIN = 12;
const unsigned long PULSE_MS = 800;
const unsigned long DEBOUNCE_MS = 25;
const unsigned long HB_MS = 450;

bool pulsing = false;
unsigned long pulseStart = 0;
int stableTrig = HIGH;
int lastTrig = HIGH;
unsigned long trigEdge = 0;
unsigned long lastHb = 0;
unsigned long shots = 0;

void injHigh()
{
    digitalWrite(INJ_PIN, HIGH);
}

void injLow()
{
    digitalWrite(INJ_PIN, LOW);
}

void setReady(bool on)
{
    digitalWrite(READY_PIN, on ? HIGH : LOW);
}

void heartbeat()
{
    Serial.print("mist shots=");
    Serial.print(shots);
    Serial.print(" busy=");
    Serial.println(pulsing ? 1 : 0);
}

void setup()
{
    pinMode(TRIG_PIN, INPUT_PULLUP);
    pinMode(INJ_PIN, OUTPUT);
    pinMode(READY_PIN, OUTPUT);
    injLow();
    setReady(true);
    Serial.begin(9600);
    stableTrig = digitalRead(TRIG_PIN);
    lastTrig = stableTrig;
    lastHb = millis();
}

void loop()
{
    unsigned long now = millis();
    int raw = digitalRead(TRIG_PIN);

    if (raw != lastTrig)
    {
        trigEdge = now;
        lastTrig = raw;
    }

    if ((now - trigEdge) >= DEBOUNCE_MS && raw != stableTrig)
    {
        stableTrig = raw;
        if (stableTrig == LOW && !pulsing)
        {
            pulsing = true;
            pulseStart = now;
            shots++;
            injHigh();
            setReady(false);
        }
    }

    if (pulsing && (now - pulseStart) >= PULSE_MS)
    {
        pulsing = false;
        injLow();
        setReady(true);
    }

    if (now - lastHb >= HB_MS)
    {
        lastHb = now;
        heartbeat();
    }
}

